  const render=()=>{const q=String($('#mobileThreadSearch')?.value||'').trim().toLowerCase();let threads=state.threads.filter(t=>tab==='archive'?Boolean(t.archived):!t.archived);if(tab==='favorite')threads=threads.filter(t=>t.pinned);if(charFilter)threads=threads.filter(t=>t.characterId===charFilter);if(q)threads=threads.filter(t=>{const c=state.characters.find(x=>x.id===t.characterId);return`${t.title||''} ${c?.name||''} ${t.folder||''} ${(t.tags||[]).join(' ')} ${(t.messages||[]).map(m=>m.content||'').join(' ')}`.toLowerCase().includes(q)});threads.sort((a,b)=>Number(b.pinned||0)-Number(a.pinned||0)||(sort==='created-desc'?String(b.createdAt||'').localeCompare(String(a.createdAt||'')):sort==='title'?String(a.title||'').localeCompare(String(b.title||''),'ko'):String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''))));const list=$('#mobileThreadList');if(!list)return;list.innerHTML=threads.length?threads.map(t=>{const c=state.characters.find(x=>x.id===t.characterId),last=t.messages?.at(-1),preview=String(last?.content||t.scene?.state||t.scene?.location||'대화를 이어가세요.').replace(/<[^>]+>/g,' ').replace(/\\s+/g,' ').trim().slice(0,150),meta=[relativeTime(t.updatedAt||t.createdAt),t.scene?.location,(t.tags||[]).slice(0,2).map(x=>'#'+x).join(' ')].filter(Boolean).join(' · ');return`<article class="mobile-thread-card-v2 ${t.archived?'archived':''}" data-thread="${t.id}"><div class="mobile-thread-portrait">${avatar(c)}</div><div class="mobile-thread-info"><div class="mobile-thread-name-row"><b>${t.pinned?'★ ':''}${esc(c?.name||'캐릭터')}</b><button type="button" class="mobile-thread-more" data-thread-more="${t.id}" aria-label="대화 메뉴">⋮</button></div><strong>${esc(t.title||'이전 대화')}</strong><p>${esc(preview)}${preview.length>=150?'…':''}</p><small>${esc(meta)}</small><button type="button" class="mobile-thread-continue" data-open-thread="${t.id}">${t.archived?'대화 보기':'이어하기'}</button></div></article>`}).join(''):`<div class="mobile-thread-empty"><b>${tab==='archive'?'보관한 대화가 없어요':tab==='favorite'?'즐겨찾기한 대화가 없어요':'조건에 맞는 대화가 없어요'}</b><span>${q?'검색어를 바꿔 보세요.':'새 대화를 시작해도 좋아요.'}</span></div>`;$$('[data-open-thread]',list).forEach(b=>b.onclick=()=>{const t=state.threads.find(x=>x.id===b.dataset.openThread);if(!t)return;state.settings.activeThreadId=t.id;state.settings.activeCharacterId=t.characterId;state.settings.activeWorkId=state.characters.find(c=>c.id===t.characterId)?.workId||state.settings.activeWorkId;saveSoon();chat()});$$('[data-thread-more]',list).forEach(b=>b.onclick=()=>threadListItemMenu(b.dataset.threadMore))};
