function threadListItemMenu(id){const t=state.threads.find(x=>x.id===id);if(!t)return;openSheet(`<div class="sheet-form"><h2>${esc(t.title||'대화')}</h2><div class="mobile-setting-menu"><button id="threadListPin"><span><b>${t.pinned?'즐겨찾기 해제':'즐겨찾기'}</b><small>대화 목록 상단에서 빠르게 찾기</small></span><em>☆</em></button><button id="threadListArchive"><span><b>${t.archived?'보관함에서 꺼내기':'보관함으로 이동'}</b><small>삭제하지 않고 목록에서 정리</small></span><em>›</em></button><button class="danger-soft" id="threadListTrash"><span><b>휴지통으로 이동</b><small>30일 동안 복원할 수 있어요.</small></span><em>›</em></button></div><button data-close>닫기</button></div>`);$('#threadListPin').onclick=()=>{t.pinned=!t.pinned;t.updatedAt=new Date().toISOString();saveSoon();closeSheet();conversationList()};$('#threadListArchive').onclick=()=>{t.archived=!t.archived;t.updatedAt=new Date().toISOString();saveSoon();closeSheet();conversationList()};$('#threadListTrash').onclick=()=>confirmSheet(`‘${t.title||'이 대화'}’을 휴지통으로 이동할까요?`,()=>{const scoped=(state.memories||[]).filter(m=>m.threadId===t.id||m.sourceThreadId===t.id);addTrash(state,'threads',t,'대화',{scopedMemories:clone(scoped)});markDeleted('threads',t.id);for(const m of scoped)markDeleted('memories',m.id);state.memories=(state.memories||[]).filter(m=>!scoped.some(x=>x.id===m.id));state.threads=state.threads.filter(x=>x.id!==t.id);saveSoon();closeSheet();conversationList()})}
