function wireMessages(){$$('.msg').forEach(el=>el.onclick=async e=>{const b=e.target.closest('button');if(!b)return;const id=el.dataset.id,m=thread().messages.find(x=>x.id===id);if(!m)return;if(b.dataset.act==='copy'){try{await navigator.clipboard.writeText(plainMessageText(m.content));say('복사했어요.')}catch{say('복사 권한을 사용할 수 없어요.',true)}}if(b.dataset.act==='delete')confirmSheet('이 메시지를 삭제할까요?',()=>{deleteMessage(id);chat()});if(b.dataset.act==='edit')textEditSheet('메시지 수정',m.content,text=>{editMessage(id,text);chat()});if(b.dataset.act==='bookmark'){toggleBookmark(id);chat()}if(b.dataset.act==='variants')variantSheet(m);if(b.dataset.act==='branch')confirmSheet('이 메시지까지의 대화로 새 분기를 만들까요?',()=>{branchFromMessage(id);chat();say('독립 대화 분기를 만들었어요.')});if(b.dataset.act==='speak')speakMessage(m);if(b.dataset.act==='regen'){if(busy)return;sending(true);try{await send('',id);chat()}catch(err){say(err.message,true);chat()}finally{sending(false)}}})}
