function trashCurrentThreadMobile(){const th=thread();if(!th)return;confirmSheet(`‘${th.title||'이 대화'}’을 휴지통으로 이동할까요?`,()=>{const scoped=(state.memories||[]).filter(m=>m.threadId===th.id||m.sourceThreadId===th.id);addTrash(state,'threads',th,'대화',{scopedMemories:clone(scoped)});markDeleted('threads',th.id);for(const m of scoped){markDeleted('memories',m.id)}state.memories=(state.memories||[]).filter(m=>!scoped.some(x=>x.id===m.id));state.threads=state.threads.filter(x=>x.id!==th.id);const next=state.threads.find(x=>!x.archived)||state.threads[0]||null;state.settings.activeThreadId=next?.id||null;state.settings.activeCharacterId=next?.characterId||state.settings.activeCharacterId;saveSoon();closeSheet();say('대화를 휴지통으로 이동했어요.');conversationList()})}
