    const collect=()=>{$$('[data-intro-index]',sheet).forEach(row=>{const i=Number(row.dataset.introIndex),b=blocks[i],type=$('[data-intro-type]',row).value;b.type=type;if(type==='image'){b.src=$('[data-intro-src]',row)?.value.trim()||'';b.caption=$('[data-intro-text]',row)?.value||''}else if(type==='button'){b.label=$('[data-intro-label]',row)?.value.trim()||'바로가기';b.href=$('[data-intro-href]',row)?.value.trim()||'#';b.text=b.label}else if(type!=='divider'){b.text=$('[data-intro-text]',row)?.value||'';if(type==='profile'||type==='card')b.title=$('[data-intro-title]',row)?.value.trim()||(type==='profile'?'프로필':'카드')}})};
