    $$('[data-intro-index]',sheet).forEach(row=>{const i=Number(row.dataset.introIndex);$('[data-intro-type]',row).onchange=()=>{collect();render()};$$('input,textarea',row).forEach(x=>x.oninput=preview);$('[data-intro-up]',row).onclick=()=>{collect();if(i>0)[blocks[i-1],blocks[i]]=[blocks[i],blocks[i-1]];render()};$('[data-intro-down]',row).onclick=()=>{collect();if(i<blocks.length-1)[blocks[i+1],blocks[i]]=[blocks[i],blocks[i+1]];render()};$('[data-intro-delete]',row).onclick=()=>{blocks.splice(i,1);render()}});
