function showMemoryEditor(m=null){openSheet(memorySheet(m));$('#memoryForm').onsubmit=e=>{e.preventDefault();const saved=saveMemory(e.currentTarget),conflicts=detectMemoryConflict(saved,state.memories.filter(x=>x.id!==saved.id&&x.characterId===saved.characterId));closeSheet();if(conflicts.length&&conflicts[0].similarity>=.45)memoryConflictSheet(saved,conflicts);else{say('기억을 저장했어요.');memoryView()}}}
function memoryConflictSheet(saved,conflicts){const top=conflicts[0];openSheet(`<div class="sheet-form"><h2>비슷하거나 충돌할 수 있는 기억</h2><p class="hint">새 기억과 기존 기억의 표현이 많이 겹쳐요. 둘 다 유지하거나 병합/교체할 수 있어요.</p>${conflicts.map(x=>`<article class="memory-card"><header><b>${esc(x.item.title||'기억')}</b><span>유사도 ${Math.round(x.similarity*100)}%</span></header><p>${esc(x.item.content||'')}</p></article>`).join('')}<div class="sheet-actions"><button id="memoryKeepBoth">둘 다 유지</button><button id="memoryMerge">병합</button><button class="primary" id="memoryReplace">기존 기억 교체</button></div></div>`);$('#memoryKeepBoth').onclick=()=>{closeSheet();say('두 기억을 모두 유지해요.');memoryView()};$('#memoryMerge').onclick=()=>{top.item.content=[top.item.content,saved.content].filter(Boolean).join('\n\n');top.item.title=top.item.title||saved.title;top.item.tags=[...new Set([...(top.item.tags||[]),...(saved.tags||[])])];top.item.importance=Math.max(Number(top.item.importance||5),Number(saved.importance||5));top.item.updatedAt=new Date().toISOString();state.memories=state.memories.filter(x=>x.id!==saved.id);saveSoon();closeSheet();say('기억을 병합했어요.');memoryView()};$('#memoryReplace').onclick=()=>{const keepId=top.item.id;Object.assign(top.item,clone(saved),{id:keepId,createdAt:top.item.createdAt,updatedAt:new Date().toISOString()});state.memories=state.memories.filter(x=>x.id!==saved.id);saveSoon();closeSheet();say('기존 기억을 새 내용으로 교체했어요.');memoryView()}}
function memorySourceSheet(m){const th=state.threads.find(x=>x.id===m.sourceThreadId),ids=new Set(m.sourceMessageIds||[]),rows=th?.messages?.filter(x=>ids.has(x.id))||[];openSheet(`<div class="sheet-form"><h2>기억 원문</h2>${rows.length?rows.map(x=>`<article class="memory-card"><header><b>${x.role==='user'?'사용자':'AI'}</b></header><p>${esc(plainMessageText(x.content))}</p></article>`).join(''):'<p class="hint">원문 메시지가 삭제되었거나 다른 백업에서 가져온 기억이에요.</p>'}${th&&rows.length?'<button class="primary" id="memoryJumpSource">원문 위치로 이동</button>':''}<button data-close>닫기</button></div>`);$('#memoryJumpSource')?.addEventListener('click',()=>{const id=rows[0].id;state.settings.activeThreadId=th.id;state.settings.activeCharacterId=th.characterId;saveSoon();closeSheet();chat();setTimeout(()=>document.querySelector(`.msg[data-id="${CSS.escape(id)}"]`)?.scrollIntoView({block:'center',behavior:'smooth'}),100)})}
function openManager(type){openFullPage(listHtml(type));wireManagerList(type)}
