function cloneManagedMobile(type,id){const src=state[type]?.find(x=>x.id===id);if(!src)return null;const copy=clone(src),stamp=Date.now().toString(36);copy.id=`${type.replace(/s$/,'')}_${stamp}_${Math.random().toString(36).slice(2,6)}`;copy.createdAt=new Date().toISOString();copy.updatedAt=copy.createdAt;if('title'in copy)copy.title=`${copy.title||types[type].label} 복사본`;if('name'in copy)copy.name=`${copy.name||types[type].label} 복사본`;if(type==='widgetTemplates')copy.versionHistory=[];state[type].push(copy);saveSoon();return copy}
function managedItemMenu(type,id){const item=state[type]?.find(x=>x.id===id);if(!item)return;const name=item.title||item.name||types[type].label;openSheet(`<div class="sheet-form"><h2>${esc(name)}</h2><div class="mobile-setting-menu"><button type="button" id="managedItemEdit"><span><b>편집</b><small>이 항목의 전체 내용을 수정</small></span><em>›</em></button><button type="button" id="managedItemClone"><span><b>복제</b><small>같은 설정의 복사본 만들기</small></span><em>⧉</em></button><button type="button" class="danger-soft" id="managedItemDelete"><span><b>삭제</b><small>참조 정리 후 휴지통/삭제 처리</small></span><em>›</em></button></div><button data-close>닫기</button></div>`);$('#managedItemEdit').onclick=()=>{closeSheet();setTimeout(()=>openManagedEditor(type,item),0)};$('#managedItemClone').onclick=()=>{cloneManagedMobile(type,id);closeSheet();say('복사본을 만들었어요.');setTimeout(()=>renderManagerPage(type),0)};$('#managedItemDelete').onclick=()=>confirmSheet(`${types[type].label} 항목을 삭제할까요?`,()=>{deleteManaged(type,id);renderManagerPage(type)})}
function wireManagerList(type){$(`[data-new-managed="${type}"]`,sheet)?.addEventListener('click',()=>openManagedEditor(type));$$(`[data-edit-managed="${type}"]`,sheet).forEach(b=>b.onclick=()=>openManagedEditor(type,state[type].find(x=>x.id===b.dataset.id)));$$(`[data-clone-managed="${type}"]`,sheet).forEach(b=>b.onclick=()=>{cloneManagedMobile(type,b.dataset.id);say('복사본을 만들었어요.');renderManagerPage(type)});$$(`[data-delete-managed="${type}"]`,sheet).forEach(b=>b.onclick=()=>confirmSheet(`${types[type].label} 항목을 삭제할까요?`,()=>{deleteManaged(type,b.dataset.id);renderManagerPage(type)}));$$(`[data-more-managed="${type}"]`,sheet).forEach(b=>b.onclick=()=>managedItemMenu(type,b.dataset.id));const selected=()=>$$('[data-managed-select]:checked',sheet).map(x=>x.value);$('#managedSelectAll',sheet)?.addEventListener('change',e=>$$('[data-managed-select]',sheet).forEach(x=>x.checked=e.target.checked));$('#managedBulkClone',sheet)?.addEventListener('click',()=>{const ids=selected();for(const id of ids)cloneManagedMobile(type,id);say(`${ids.length}개 복사본을 만들었어요.`);renderManagerPage(type)});$('#managedBulkDelete',sheet)?.addEventListener('click',()=>{const ids=selected();if(!ids.length)return;shellConfirmBulk(type,ids)});$('#managedBulkToggle',sheet)?.addEventListener('click',()=>{const ids=selected();for(const id of ids){const x=state[type]?.find(y=>y.id===id);if(x&&'enabled'in x)x.enabled=x.enabled===false}saveSoon();say('선택 항목 사용 상태를 전환했어요.');renderManagerPage(type)});$('#managedBulkTags',sheet)?.addEventListener('click',()=>{const ids=selected();if(!ids.length){say('먼저 항목을 선택해 주세요.',true);return}textEditSheet('선택 항목에 태그 추가','',raw=>{const tags=raw.split(',').map(x=>x.trim()).filter(Boolean);if(!tags.length)return;for(const id of ids){const x=state[type]?.find(y=>y.id===id);if(!x)continue;x.tags=[...new Set([...(Array.isArray(x.tags)?x.tags:[]),...tags])];x.updatedAt=new Date().toISOString()}saveSoon();say(`${ids.length}개 항목에 태그를 추가했어요.`);renderManagerPage(type)})});$('#managedBulkExport',sheet)?.addEventListener('click',()=>{const ids=selected();if(!ids.length){say('먼저 항목을 선택해 주세요.',true);return}const items=(state[type]||[]).filter(x=>ids.includes(x.id));mobileDownloadJson(`LumiChat_${type}_선택_${items.length}.json`,{type:'lumichat-selection',collection:type,exportedAt:new Date().toISOString(),items});say(`${items.length}개 항목을 내보냈어요.`)})}
function shellConfirmBulk(type,ids){confirmSheet(`${ids.length}개 항목을 휴지통으로 이동할까요?`,()=>{for(const id of ids)deleteManaged(type,id);renderManagerPage(type)})}
function openManagedEditor(type,item=null){openFullPage(editorHtml(type,item));const form=$('#managedForm');if(type==='widgetTemplates'&&item){const tools=document.createElement('div');tools.className='widget-editor-mobile-tools';tools.innerHTML=`<button type="button" id="mobileWidgetAudit">검사</button><button type="button" id="mobileWidgetHistory" ${(item.versionHistory||[]).length?'':'disabled'}>이전 버전 ${(item.versionHistory||[]).length}</button>`;form.querySelector('.sheet-actions')?.before(tools);$('#mobileWidgetAudit').onclick=()=>{const fields=String(form.elements.fields.value||'').split(/\n/).map(line=>{const [key,...rest]=line.split('::');return{key:key?.trim(),instruction:rest.join('::').trim()}}).filter(x=>x.key),r=validateWidgetTemplate({fields,template:form.elements.template.value});openSheet(`<div class="sheet-form"><h2>위젯 검사</h2>${r.errors.length?`<div class="audit-bad"><b>오류</b>${r.errors.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:'<p class="audit-good">필수 오류가 없어요.</p>'}${r.warnings.length?`<div class="audit-warn"><b>확인 권장</b>${r.warnings.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}<button data-close>닫기</button></div>`)};$('#mobileWidgetHistory').onclick=()=>widgetHistorySheet(item)}form.onsubmit=e=>{e.preventDefault();if(type==='widgetTemplates'){const fields=String(form.elements.fields.value||'').split(/\n/).map(line=>{const [key,...rest]=line.split('::');return{key:key?.trim(),instruction:rest.join('::').trim()}}).filter(x=>x.key),r=validateWidgetTemplate({fields,template:form.elements.template.value});if(r.errors.length){say(`위젯 오류 ${r.errors.length}개를 먼저 고쳐 주세요.`,true);return}}saveManaged(type,form);closeSheet();say(`${types[type].label}을 저장했어요.`);setTimeout(()=>renderManagerPage(type),0)}}
function widgetHistorySheet(item){const rows=item.versionHistory||[];openSheet(`<div class="sheet-form"><h2>위젯 이전 버전</h2>${rows.length?rows.map((v,i)=>`<article class="mobile-history-row"><div><b>${esc(v.title||item.title||'위젯')}</b><small>${new Date(v.savedAt).toLocaleString('ko-KR')}</small></div><button data-widget-revert="${i}">되돌리기</button></article>`).join(''):'<p class="hint">저장된 이전 버전이 없어요.</p>'}<button data-close>닫기</button></div>`);$$('[data-widget-revert]',sheet).forEach(b=>b.onclick=()=>confirmSheet('이 버전으로 되돌릴까요? 현재 버전은 기록에 보관됩니다.',()=>{const v=rows[Number(b.dataset.widgetRevert)];if(!v)return;const current={id:`widgetver_${Date.now()}`,savedAt:new Date().toISOString(),title:item.title,description:item.description,fields:clone(item.fields||[]),template:item.template,display:clone(item.display||{})};item.versionHistory=[current,...rows.filter((_,i)=>i!==Number(b.dataset.widgetRevert))].slice(0,30);Object.assign(item,{title:v.title||item.title,description:v.description||'',fields:clone(v.fields||[]),template:v.template||'',display:clone(v.display||{})});item.updatedAt=new Date().toISOString();saveSoon();closeSheet();say('위젯을 이전 버전으로 되돌렸어요.');renderManagerPage('widgetTemplates')}))}
function widgetLibrary(){const custom=state.widgetTemplates||[];openSheet(`<div class="sheet-form"><h2>기본 · 내 위젯</h2><p class="hint">상태 위젯은 AI 답변의 상태값만 저장하고 이전 턴에도 그대로 남습니다. 사용자 이름과 캐릭터 이름은 자동 치환돼요.</p><div class="widget-library-list">${builtInWidgets.map(w=>`<article class="widget-lib-card"><div><b>${esc(widgetTitle(w,{personaId:state.personas[0]?.id,characterId:char()?.id,workId:char()?.workId,title:'미리보기',scene:{}}))}</b><p>${esc(w.description)}</p></div><button data-preview-widget="${w.id}">미리보기</button></article>`).join('')}${custom.map(w=>`<article class="widget-lib-card"><div><b>${esc(w.title)}</b><p>${esc(w.description||'내 위젯')}</p></div></article>`).join('')}</div><button id="goMyWidgets">내 위젯 편집</button><button data-close>닫기</button></div>`);$$('[data-preview-widget]',sheet).forEach(b=>b.onclick=()=>previewWidget(builtInWidgets.find(x=>x.id===b.dataset.previewWidget)));$('#goMyWidgets').onclick=()=>openManager('widgetTemplates')}
function fitMobilePreviewWidget(frame){if(!frame)return;const apply=()=>{try{const d=frame.contentDocument;if(!d)return;d.documentElement.style.overflow='visible';d.documentElement.style.height='auto';if(d.body){d.body.style.overflow='visible';d.body.style.height='auto'}frame.style.setProperty('height',`${Math.min(3200,Math.max(120,d.documentElement.scrollHeight||0,d.body?.scrollHeight||0)+4)}px`,'important')}catch{}};frame.addEventListener('load',()=>{requestAnimationFrame(apply);setTimeout(apply,180)},{once:true})}
function previewWidget(w){const values=Object.fromEntries(w.fields.map(f=>[f.key,({날짜:'785년 7월 7일 월요일',시간:'오후',날씨:'맑음',장소:'아르젠트 대공가',세부장소:'식료품 저장실',오늘생긴일:'수상한 장부 오차를 발견했다.',할일:'☐ 장부 값 맞춰보기',끝낸일:'☑ 저장실 재고 확인',약속일정:'○ 저녁에 집사실 들르기',소지품:'장부 · 저장실 열쇠',관계요약:'대공과 신입 하인. 서로의 능력을 눈여겨보기 시작했다.',관계단계:'고용주와 신입 하인 · 능력을 인정하기 시작함',스킨십진도:'없음',키스횟수:'0회',관계횟수:'0회',연애Dday:'—',연애시작일:'없음',결혼Dday:'—',결혼일:'없음',캐릭터복장:'검은 집무복과 장갑',사용자복장:'남장 하인복과 앞치마',캐릭터감상:'말은 많지만 숫자 보는 눈은 확실하군.',사용자감상:'성격까지 옷처럼 단정했으면 좋겠는데.',우리약속:'조사 결과는 둘이 먼저 확인하기',처음기록:'첫 포옹 · 아직\n첫 입맞춤 · 아직\n첫 관계 · 아직',기억할날:'785년 7월 7일 · 처음 함께 장부를 조사한 날',캐릭터속생각:'평범한 하인이라기엔 계산이 지나치게 빠르다.',캐릭터위시:'아무 일 없이 차 한 잔 마시기',사용자속생각:'괜히 빤히 보는 건 마음에 안 든다.',사용자위시:'따뜻한 사과 파이 먹기',캐릭터한마디:'틀린 곳을 전부 찾아라.',사용자한마디:'저 지금 일 하나 더 늘어난 거 맞죠?',소문:'저장실 하인: 대공 전하가 장부를 직접 보는 건 오랜만이래.\n주방 하녀: 그 신입, 숫자 계산을 엄청 잘한다던데.',끄적질문자:'카이런 아르젠트',끄적질문:'너 진짜 꼬박꼬박 말대꾸는 잘하는구나.',끄적답변자:'에레나 베르티에',끄적답변:'제가요??'}[f.key]||'미정')]));openSheet(`<div class="sheet-form"><h2>위젯 미리보기</h2><div class="row preview-device-row"><button class="primary" data-preview-device="mobile">휴대폰 390px</button><button data-preview-device="desktop">PC 760px</button></div><div class="widget-preview-frame mobile" id="widgetPreviewHost"><iframe sandbox="allow-same-origin" id="previewWidgetFrame"></iframe></div><button data-close>닫기</button></div>`);const frame=$('#previewWidgetFrame'),host=$('#widgetPreviewHost');fitMobilePreviewWidget(frame);frame.srcdoc=widgetDocument(w,values,{characterId:char()?.id,personaId:state.personas.find(x=>x.workId===char()?.workId)?.id,workId:char()?.workId,title:'미리보기',scene:{location:'식료품 저장실'}});$$('[data-preview-device]',sheet).forEach(b=>b.onclick=()=>{$$('[data-preview-device]',sheet).forEach(x=>x.classList.toggle('primary',x===b));host.classList.toggle('desktop',b.dataset.previewDevice==='desktop');host.classList.toggle('mobile',b.dataset.previewDevice!=='desktop')})}
function widgetPicker(){const th=thread(),c=char();if(!th||!c)return;const all=[...builtInWidgets,...(state.widgetTemplates||[])];openSheet(`<div class="sheet-form"><h2>상태 위젯</h2><p class="hint">체크한 위젯은 다음 AI 답변부터 갱신됩니다. 캐릭터 기본값으로 저장하면 새 대화에도 자동 적용돼요.</p>${all.map(w=>{const active=(th.statusWidgets||[]).some(x=>x.presetId===w.id||x.libraryTemplateId===w.id||x.id===w.id);return`<label class="widget-check"><input type="checkbox" data-widget-pick value="${w.id}" ${active?'checked':''}><span><b>${esc(widgetTitle(w,th))}</b><small>${esc(w.description||'')}</small></span></label>`}).join('')}<label class="check"><input id="saveWidgetDefaults" type="checkbox"> 현재 선택을 ${esc(c.name)}의 새 대화 기본값으로 저장</label><div class="sheet-actions"><button type="button" data-close>취소</button><button class="primary" id="applyWidgets">적용</button></div></div>`);$('#applyWidgets').onclick=()=>{const ids=$$('[data-widget-pick]:checked',sheet).map(x=>x.value);th.statusWidgets=all.filter(w=>ids.includes(w.id)).map(w=>{const old=(th.statusWidgets||[]).find(x=>x.presetId===w.id||x.libraryTemplateId===w.id||x.id===w.id);return old||widgetCopy(w)});if($('#saveWidgetDefaults').checked)c.defaultStatusWidgetPresetIds=ids.filter(id=>builtInWidgets.some(w=>w.id===id));saveSoon();closeSheet();say('상태 위젯을 적용했어요.');chat()}}
function migrateLedgerV2(){const stock=builtInWidgets.find(w=>w.id==='builtin-user-ledger-v1');if(!stock)return;for(const th of state.threads||[]){th.statusWidgets=(th.statusWidgets||[]).map(w=>{const isLedger=[w.id,w.presetId,w.libraryTemplateId].includes('builtin-user-ledger-v1');if(!isLedger)return w;const legacy=(w.fields||[]).some(f=>['캐릭터시선','사용자시선','끄적1','끄적2'].includes(f.key))||!(w.fields||[]).some(f=>f.key==='스킨십진도');if(!legacy)return w;const id=w.id,presetId=w.presetId||'builtin-user-ledger-v1';return {...widgetCopy(stock),id,presetId,enabled:w.enabled!==false}});for(const w of th.statusWidgets||[]){if(w.presetId!=='builtin-user-ledger-v1'&&w.id!=='builtin-user-ledger-v1')continue;const v=th.statusWidgetState?.[w.id]?.values;if(!v)continue;if(v.캐릭터시선&&!v.캐릭터감상)v.캐릭터감상=v.캐릭터시선;if(v.사용자시선&&!v.사용자감상)v.사용자감상=v.사용자시선;if(v.끄적1&&!v.끄적질문){v.끄적질문자=char(th.characterId)?.name||'캐릭터';v.끄적질문=v.끄적1}if(v.끄적2&&!v.끄적답변){v.끄적답변자=state.personas.find(p=>p.id===th.personaId)?.name||state.profile.name||'사용자';v.끄적답변=v.끄적2}delete v.캐릭터시선;delete v.사용자시선;delete v.끄적1;delete v.끄적2}}saveSoon()}
function settings(){
  activeNav('settings');const sync=getSyncMeta(),tts=state.settings.tts||{};
  app.innerHTML=`<header class="page-head"><div><small>SETTINGS · v${APP_VERSION}</small><h1>앱 설정</h1></div></header><section class="settings-card"><h2>저장 상태</h2><div id="settingsSyncStatus" class="mobile-sync-panel ${sync.dirty?'dirty':'synced'}"><b>${sync.dirty?'로컬에는 저장됨 · 서버 동기화 대기':'서버까지 동기화됨'}</b><small>${sync.lastSyncedAt?`마지막 서버 동기화 ${new Date(sync.lastSyncedAt).toLocaleString('ko-KR')}`:'아직 서버 동기화 기록 없음'}</small></div></section><section class="settings-card"><h2>사용자</h2><label>기본 사용자 이름<input id="profileName" value="${esc(state.profile.name||'사용자')}"></label><label>기본 사용자 대사 글씨색<input id="profileDialogueColor" type="color" value="${esc(state.profile.dialogueTextColor||speakerTextColor('pc','persona:user','#65b9ff'))}"></label><p class="hint">대화별 유저 프로필을 선택하면 해당 프로필 이름이 우선됩니다.</p></section><section class="settings-card theme-settings-card"><h2>화면 테마</h2><p class="hint">PC와 같은 테마 ID를 사용합니다. 사용자 HTML 위젯 내부 디자인은 그대로 보존됩니다.</p><div class="mobile-theme-grid">${mobileThemeCards()}</div></section><section class="settings-card"><h2>AI 연결</h2><label>제공자<select id="provider"><option value="google">Google AI</option><option value="openai">OpenAI</option><option value="anthropic">Anthropic</option><option value="openrouter">OpenRouter</option><option value="custom">Custom</option></select></label><label>모델 ID<input id="model" value="${esc(state.settings.defaultModel||'gemini-3.6-flash')}"></label><label>API Key<input id="apiKey" type="password" autocomplete="off" placeholder="서버에 저장 · 브라우저 저장 안 함"></label><div class="row"><button id="saveAI" class="primary">AI 연결 저장</button><button id="testAI">연결 테스트</button></div></section><section class="settings-card"><h2>저장·백업</h2><div class="tool-list compact"><button id="saveCloud"><b>지금 저장</b><span>폰 → 서버 동기화</span></button><button id="pullCloud"><b>서버에서 불러오기</b><span>현재 기기에 적용</span></button><button id="exportBtn"><b>백업 내보내기</b><span>PC와 호환되는 JSON</span></button><label class="upload-btn"><b>백업 불러오기</b><span>내용 미리보기 후 복원</span><input id="importBtn" type="file" accept="application/json" hidden></label><button id="trashBtn"><b>휴지통</b><span>${(state.settings.trash||[]).length}개 · 30일 복원</span></button></div><div class="recovery-key-box"><div><b>기기 복구키</b><small>브라우저 데이터가 지워져도 같은 서버 저장본에 다시 연결할 수 있어요. 비밀번호처럼 따로 보관하세요.</small></div><code id="recoveryKeyValue">${esc(getRecoveryKey())}</code><div class="row"><button id="copyRecoveryKey">복구키 복사</button><button id="restoreRecoveryKey">다른 복구키로 연결</button></div></div></section><section class="settings-card"><h2>음성 읽기</h2><button id="openTtsSettings"><b>음성·속도·자동 읽기</b><span>${tts.autoRead?'새 답변 자동 읽기 켜짐':'필요할 때 읽기'}</span></button></section><section class="settings-card"><h2>대화 기본값</h2><label>입력 문맥 프리셋<select id="inputPreset"><option value="3000" ${Number(state.settings.inputContextTokens||5000)===3000?'selected':''}>절약 · 3,000t</option><option value="5000" ${Number(state.settings.inputContextTokens||5000)===5000?'selected':''}>보통 · 5,000t</option><option value="7000" ${Number(state.settings.inputContextTokens||5000)===7000?'selected':''}>풍부 · 7,000t</option><option value="10000" ${Number(state.settings.inputContextTokens||5000)===10000?'selected':''}>장기 RP · 10,000t</option><option value="custom" ${![3000,5000,7000,10000].includes(Number(state.settings.inputContextTokens||5000))?'selected':''}>직접 입력</option></select></label><label>입력 최대 토큰<input id="inputTokens" type="number" min="2000" max="30000" step="100" value="${state.settings.inputContextTokens||5000}"></label><label>응답 최대 토큰<input id="maxTokens" type="number" min="256" max="65536" value="${state.settings.maxTokens||1800}"></label><label>Temperature<input id="temp" type="number" min="0" max="2" step="0.05" value="${state.settings.temperature||.85}"></label></section>`;
  const p=$('#provider');p.value=state.settings.defaultProvider||'google';$$('[data-mobile-theme]').forEach(button=>button.onclick=()=>{state.profile.theme=button.dataset.mobileTheme;applyMobileTheme(state.profile.theme);$$('[data-mobile-theme]').forEach(x=>x.classList.toggle('active',x===button));saveSoon()});$('#profileName').onchange=e=>{state.profile.name=e.target.value.trim()||'사용자';saveSoon()};const color=$('#profileDialogueColor');const contrast=()=>mobileContrastStatus(color,'#000000');color.oninput=contrast;color.onchange=e=>{state.profile.dialogueTextColor=e.target.value;saveSoon();contrast()};contrast();$('#saveAI').onclick=async()=>{try{const provider=p.value,model=$('#model').value.trim(),apiKey=$('#apiKey').value.trim();await edge('provider-config-set',{provider,apiKey,defaultModel:model});state.settings.defaultProvider=provider;state.settings.defaultModel=model;$('#apiKey').value='';saveSoon();say('AI 연결을 서버에 저장했어요.')}catch(e){say(e.message,true)}};$('#testAI').onclick=async()=>{try{await edge('provider-test',{provider:p.value,model:$('#model').value.trim()});say('AI 연결 정상이에요.')}catch(e){say(e.message,true)}};$('#saveCloud').onclick=async()=>{try{await save(false);say('서버에 저장했어요.');settings()}catch(e){say(e.message,true)}};$('#pullCloud').onclick=()=>confirmSheet('서버 저장본으로 현재 기기 상태를 바꿀까요?',async()=>{try{await pull(true);say('서버 저장본으로 현재 기기를 교체했어요.');home()}catch(e){say(e.message,true)}});$('#exportBtn').onclick=exportState;$('#trashBtn').onclick=trashSheet;$('#openTtsSettings').onclick=()=>ttsSettingsSheet('default');$('#importBtn').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const raw=JSON.parse(await file.text()),next=raw.state||raw,summary=`캐릭터 ${(next.characters||[]).length}개 · 대화 ${(next.threads||[]).length}개 · 기억 ${(next.memories||[]).length}개 · 위젯 ${(next.widgetTemplates||[]).length}개 · Schema ${next.schemaVersion||'?'}`;openSheet(`<div class="sheet-form"><h2>백업 복원 미리보기</h2><p>${esc(summary)}</p><p class="hint">안전 병합은 현재 기기의 최신 항목과 백업을 ID·수정시각 기준으로 합칩니다. 전체 교체는 현재 상태를 백업 내용으로 바꿉니다.</p><div class="sheet-actions"><button data-close>취소</button><button id="importMerge">안전 병합</button><button class="primary" id="importReplace">전체 교체</button></div></div>`);const run=async mode=>{try{await importState(file,mode);await installPortableFonts();closeSheet();say(mode==='merge'?'백업을 안전 병합했어요.':'백업으로 현재 상태를 교체했어요.');home()}catch(err){say(err.message,true)}};$('#importMerge').onclick=()=>run('merge');$('#importReplace').onclick=()=>confirmSheet('현재 상태를 이 백업으로 완전히 교체할까요?',()=>run('replace'))}catch(err){say('백업 파일을 읽을 수 없어요.',true)}};$('#copyRecoveryKey').onclick=async()=>{try{await navigator.clipboard.writeText(getRecoveryKey());say('복구키를 복사했어요. 안전한 곳에 보관해 주세요.')}catch{say('복사 권한을 사용할 수 없어요.',true)}};$('#restoreRecoveryKey').onclick=()=>textEditSheet('기기 복구키 입력','',async value=>{try{setRecoveryKey(value);await pull(true);say('복구키의 서버 저장본에 연결했어요.');home()}catch(err){say(err.message,true)}});const inputPreset=$('#inputPreset'),inputTokens=$('#inputTokens');inputPreset.onchange=()=>{if(inputPreset.value!=='custom'){inputTokens.value=inputPreset.value;state.settings.inputContextTokens=Number(inputPreset.value);saveSoon()}};inputTokens.onchange=()=>{const v=Math.max(2000,Math.min(30000,Number(inputTokens.value||5000)));inputTokens.value=v;state.settings.inputContextTokens=v;inputPreset.value=[3000,5000,7000,10000].includes(v)?String(v):'custom';saveSoon()};$('#maxTokens').onchange=e=>{state.settings.maxTokens=Number(e.target.value);saveSoon()};$('#temp').onchange=e=>{state.settings.temperature=Number(e.target.value);saveSoon()}
}
function showMobilePwaUpdate(reg){if(!reg?.waiting||document.querySelector('.pwa-update-card'))return;const card=document.createElement('div');card.className='pwa-update-card';card.innerHTML='<span><b>새 LumiChat 버전이 준비됐어요.</b><small>입력 중인 초안은 저장된 뒤 업데이트됩니다.</small></span><button class="primary">업데이트</button>';document.body.append(card);card.querySelector('button').onclick=()=>{reg.waiting.postMessage({type:'SKIP_WAITING'});card.remove()}}
async function registerMobilePwa(){if(!('serviceWorker'in navigator))return;try{const reg=await navigator.serviceWorker.register('./sw.js');showMobilePwaUpdate(reg);reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)showMobilePwaUpdate(reg)})});let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloading)return;reloading=true;location.reload()})}catch(e){console.warn(e)}}
window.addEventListener('lumichat-sync-status',e=>{const meta=e.detail||getSyncMeta(),badge=$('#mobileSyncBadge'),panel=$('#settingsSyncStatus');if(badge){badge.className=`mobile-sync-badge ${meta.dirty?'dirty':'synced'}`;badge.textContent=meta.dirty?'로컬 저장 · 동기화 대기':'서버 동기화됨'}if(panel){panel.className=`mobile-sync-panel ${meta.dirty?'dirty':'synced'}`;panel.querySelector('b').textContent=meta.dirty?'로컬에는 저장됨 · 서버 동기화 대기':'서버까지 동기화됨'}});
$$('.bottom-nav button').forEach(b=>b.onclick=()=>({home,chat:conversationList,library:libraryView,memory:memoryView,settings}[b.dataset.view]||home)());sheet.addEventListener('click',e=>{if(e.target.matches('[data-close]'))closeSheet()});window.addEventListener('popstate',()=>{if(ignoreNextPop){ignoreNextPop=false;return}if(!sheet.hidden){closeSheet(true);return}if($('.chat-page'))conversationList()});history.replaceState({root:true},'',location.href);const setVh=()=>{const vv=window.visualViewport;const h=Math.max(1,Math.round(vv?.height||innerHeight));document.documentElement.style.setProperty('--vh',`${h}px`);document.body.classList.toggle('keyboard-open',!!vv&&innerHeight-h>120)};window.addEventListener('resize',setVh,{passive:true});window.visualViewport?.addEventListener('resize',setVh,{passive:true});window.visualViewport?.addEventListener('scroll',setVh,{passive:true});setVh();
(async()=>{setVh();const r=await boot();applyMobileTheme();await installPortableFonts();migrateLedgerV2();home();clearTimeout(window.__lumiBootWatch);$('#boot')?.remove();if(!r.online)say('오프라인 저장본으로 열었어요.',true);await registerMobilePwa()})();
